#!/usr/bin/env python3
"""Generate the static, acyclic reusable-workflow adapters. Commit generated YAML."""
import argparse
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parent / "lib"))
from shard_capacity import MAX_GROUP_LEVELS, dispatcher_name

WORKFLOWS = Path(__file__).resolve().parents[2] / "workflows"


def render(index):
    remaining = MAX_GROUP_LEVELS - index + 1
    header = f"""# Generated by .github/actions/clippier/generate-dispatchers.py; do not edit.
name: Nested build group ({remaining} levels available)

on:
    workflow_call:
        inputs:
            node-id:
                type: string
                required: true
            node-kind:
                type: string
                required: true

jobs:
    prepare:
        runs-on: ubuntu-latest
        outputs:
            matrix: ${{{{ steps.matrix.outputs.value }}}}
        steps:
            - uses: actions/checkout@v6
            - uses: actions/download-artifact@v8
              with:
                  name: clippier-case-plan
                  path: plan
            - name: Read bounded child matrix
              id: matrix
              shell: bash
              env:
                  NODE_ID: ${{{{ inputs.node-id }}}}
                  NODE_KIND: ${{{{ inputs.node-kind }}}}
              run: |
                  # Validate even leaf/invalid inputs before selecting a branch.
                  [[ "$NODE_KIND" == group || "$NODE_KIND" == leaf ]] || {{ echo 'Invalid node kind' >&2; exit 1; }}
                  matrix=$(python3 .github/actions/clippier/lib/shard_tree.py read plan/hierarchy "$NODE_ID" "$NODE_KIND" --remaining-levels {remaining})
                  if [[ "$NODE_KIND" == group ]]; then
                      echo "value=$matrix" >> "$GITHUB_OUTPUT"
                  else
                      echo 'value=[]' >> "$GITHUB_OUTPUT"
                  fi
"""
    if remaining > 1:
        header += f"""
    children:
        if: inputs.node-kind == 'group'
        needs: prepare
        name: ${{{{ matrix.child.name }}}}
        strategy:
            fail-fast: false
            matrix:
                child: ${{{{ fromJson(needs.prepare.outputs.matrix) }}}}
        uses: ./.github/workflows/{dispatcher_name(index + 1)}
        with:
            node-id: ${{{{ matrix.child.id }}}}
            node-kind: ${{{{ matrix.child.kind }}}}
        secrets: inherit
"""
    header += """
    leaf:
        if: inputs.node-kind == 'leaf'
        needs: prepare
        uses: ./.github/workflows/clippier-build-shard.yml
        with:
            node-id: ${{ inputs.node-id }}
        secrets: inherit
"""
    return header


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    mismatches = []
    for index in range(1, MAX_GROUP_LEVELS + 1):
        path = WORKFLOWS / dispatcher_name(index)
        expected = render(index)
        if args.check:
            if not path.exists() or path.read_text() != expected:
                mismatches.append(path.name)
        else:
            path.write_text(expected)
    if mismatches:
        sys.exit("Dispatcher drift; regenerate: " + ", ".join(mismatches))


if __name__ == "__main__":
    main()
